dex_aggregator.integrationCode:
const swapRoute = await dexAggregator.findBestRoute({
  tokenIn: usdc,
  tokenOut: usdt,
  amount: 1000n
});

const footprint = await detectArchivedKeys(swapRoute.contracts);
const restored = await restoreKeys(footprint);

const result = await executeSwap({
