  footprint: restored
});

lending_protocol.integrationCode:
const position = await lendingPool.getPosition(userAddress);
const health = await calculateHealthFactor(position);

if (health < 1.0) {
  const affectedKeys = await detectLiquidationKeys(position);
  const footprint = await restoreKeys(affectedKeys);

  const liquidation = await executeLiquidation({
    position,
    collateral: position.collateral,
    footprint
  });

  return liquidation.reward;
}

nft_marketplace.integrationCode:
