bridge_contract.integrationCode:
const validators = await bridgeContract.getValidators();
const affectedKeys = await detectValidatorKeys(validators);
const footprint = await restoreKeys(affectedKeys);

const signatures = await collectSignatures({
  validators,
  message: bridgeMessage,
  footprint
});

if (signatures.length >= threshold) {
  await executeBridgeTransaction({
    message: bridgeMessage,
    signatures,
    footprint
  });
}

yield_aggregator.integrationCode:
const strategies = [
  { contract: strategyA, allocation: 40n },
  { contract: strategyB, allocation: 35n },
  { contract: strategyC, allocation: 25n }
];

const allKeys = await detectArchivedKeys(
  strategies.map(s => s.contract)
);
const footprint = await restoreKeys(allKeys);

const executed = await executeComposedStrategy({
  strategies,
  amount: depositAmount,
  footprint
});

await trackYield(executed);
